// ============================================================
// COMPILE DAILY PIPELINE HEALTH REPORT
// ============================================================

const successItems = $('Read Success Log').all();
const filteredItems = $('Read Filtered Log').all();

const now = new Date();
const yesterday = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const yesterdayISO = yesterday.toISOString().split('T')[0];

// Count items from the last 24 hours
function countRecent(items) {
  return items.filter(item => {
    const ts = item.json.timestamp || '';
    return ts >= yesterdayISO;
  }).length;
}

function countRecentByReason(items, reason) {
  return items.filter(item => {
    const ts = item.json.timestamp || '';
    return ts >= yesterdayISO && (item.json.reason || '').includes(reason);
  }).length;
}

const successCount = countRecent(successItems);
const filteredCount = countRecent(filteredItems);
const totalProcessed = successCount + filteredCount;

const titleFiltered = countRecentByReason(filteredItems, 'title');
const locationFiltered = countRecentByReason(filteredItems, 'location');
const industryFiltered = countRecentByReason(filteredItems, 'industry');
const noEmailCount = countRecentByReason(filteredItems, 'no_email');

const icpRate = totalProcessed > 0 ? ((successCount / totalProcessed) * 100).toFixed(1) : '0';

// Alert flags
const alerts = [];
if (totalProcessed === 0) alerts.push('WARNING: Zero leads processed in last 24h — check Cornersight webhook');
if (parseFloat(icpRate) < 5 && totalProcessed > 0) alerts.push('WARNING: ICP match rate below 5% — review filter settings');

const report = `
PIPELINE DAILY REPORT — ${yesterdayISO}
========================================

Leads processed:        ${totalProcessed}
ICP matches (success):  ${successCount} (${icpRate}%)
Filtered out:           ${filteredCount}

Filter breakdown:
  - Title mismatch:     ${titleFiltered}
  - Location mismatch:  ${locationFiltered}
  - Industry mismatch:  ${industryFiltered}
  - No email found:     ${noEmailCount}

${alerts.length > 0 ? '\nALERTS:\n' + alerts.map(a => '  ' + a).join('\n') : 'No alerts.'}
`.trim();

return [{
  json: {
    report,
    total_processed: totalProcessed,
    success_count: successCount,
    filtered_count: filteredCount,
    icp_rate: icpRate,
    alerts: alerts,
    date: yesterdayISO
  }
}];
